INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000102', 'AN0101', '楼蘭', '楼蘭（ろうらん、樓蘭、英語：Loulan、推定されている現地名はクロライナ Kroraina）は、中央アジア、タリム盆地のタクラマカン砂漠北東部（現在の中国・新疆ウイグル自治区チャルクリク）に、かつて存在した都市、及びその都市を中心とした国家。「さまよえる湖」ロプノールの西岸に位置し、シルクロードが西域南道と天山南路に分岐する要衝にあって、交易により栄えた。 紀元前77年に漢の影響下で国名を鄯善（', 18, '女性', 244995) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000103', 'AN0101', '虞淵', NULL, NULL, '男性', 274192) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000104', 'AN0101', '皇帝', '皇帝（こうてい、英語: emperor, king of kings, the King、ドイツ語: Kaiser、ラテン語: imperator、ロシア語: император, царь、ギリシア語: αὐτοκράτωρ, Βασιλεὺς βασιλέων、中国語: 皇帝）は、帝国君主の総称。王の中の王（諸王の王）、君主国の君主の称号。皇帝という君主号には「唯一神」の意味や模倣・僭称も存在', 35, '男性', 144110) ON CONFLICT DO NOTHING;
